// intent: learn how `pi-agent run` picks its workdir and where report.json goes
const r = await tools.bash({ command: "npm run dev -- run --help 2>&1 | tail -40; echo ---; rg -n 'workdir|--out|report.json' README.md | head -30" });
text(r.output);

// @options: {"timeout_ms": 600000}
// intent: build a buggy fixture in /tmp, run the debugger task on it, and capture report + file diff
const setup = `set -e
D=/tmp/debugger-fixture; rm -rf $D; mkdir -p $D; cd $D
cat > cart.js <<'EOF'
// Sum of item prices with a quantity discount: 10% off lines with qty >= 10.
function lineTotal(item) {
  const base = item.price * item.qty;
  return item.qty > 10 ? base * 0.9 : base;
}
function cartTotal(items) {
  return items.reduce((sum, it) => sum + lineTotal(it), 0);
}
module.exports = { lineTotal, cartTotal };
EOF
cat > cart.test.js <<'EOF'
const test = require("node:test");
const assert = require("node:assert/strict");
const { lineTotal, cartTotal } = require("./cart.js");
test("no discount under 10", () => assert.equal(lineTotal({ price: 2, qty: 9 }), 18));
test("10% off at qty 10", () => assert.equal(lineTotal({ price: 2, qty: 10 }), 18));
test("cart sums lines", () => assert.equal(cartTotal([{ price: 1, qty: 1 }, { price: 2, qty: 10 }]), 19));
EOF
cat > package.json <<'EOF'
{ "name": "cart", "private": true, "scripts": { "test": "node --test" } }
EOF
printf '.agent-out/\\n' > .gitignore
git init -q && git add -A && git -c user.email=t@t -c user.name=t commit -qm init
echo fixture ready`;
const s = await tools.bash({ command: setup });
const run = await tools.bash({ command: "npm run dev -- run --task examples/task.debugger.json --workdir /tmp/debugger-fixture 2>&1 | tail -30; echo exit ${PIPESTATUS[0]}", timeout: 580 });
const after = await tools.bash({ command: "cd /tmp/debugger-fixture && echo '--- git status' && git status --short && echo '--- report' && cat .agent-out/report.json && echo && ls .agent-out" });
text(s.output); text(run.output); text(after.output);

